import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import vm from "node:vm";

// The page is generated by our own server; slice its single inline script.
const html = readFileSync(0, "utf8"), start = html.indexOf("<script>") + "<script>".length;
const script = html.slice(start, html.indexOf("</script>", start));
const timers = new Map(), sockets = [], requests = [];
let sequence = 0, response = { wsPort: 2233 }, status = 200, stalled = false;
class Socket {
    constructor(url) { this.url = new URL(url); this.events = {}; sockets.push(this); }
    addEventListener(name, fn) { this.events[name] = fn; }
    close() { this.events.close(); }
}
const window = {
    setTimeout(fn, delay) { const id = ++sequence; timers.set(id, { fn, delay }); return id; },
    clearTimeout(id) { timers.delete(id); },
};
vm.runInNewContext(script, {
    window, WebSocket: Socket, AbortController,
    location: { hostname: "localhost" },
    document: { getElementById: () => ({}), documentElement: { style: { setProperty() {} } } },
    fetch: async (url, options) => {
        requests.push([url, options]);
        if (stalled) return new Promise((resolve, reject) => {
            options.signal.addEventListener("abort", () => reject(new Error("aborted")));
        });
        return { ok: status === 200, json: async () => response };
    },
});
const retry = async () => {
    const [id, timer] = timers.entries().next().value;
    timers.delete(id);
    await timer.fn();
    // Allow async refresh and its finally block to finish.
    await new Promise(resolve => setImmediate(resolve));
    return timer.delay;
};
assert.equal(sockets[0].url.port, "2231");
sockets[0].events.open();
sockets[0].close(); // No SETTINGS_UPDATED notification is delivered.
assert.equal(await retry(), 500);
assert.equal(sockets[1].url.port, "2233", "an existing page must discover a changed WebSocket port");
assert.equal(sockets[1].url.searchParams.get("token"), "test-token");
assert.equal(requests[0][0], "/obs/connection");
assert.equal(requests[0][1].headers.Authorization, "Bearer test-token");
assert.equal(requests[0][1].cache, "no-store");
assert.equal(requests[0][1].referrerPolicy, "no-referrer");
assert.ok(requests[0][1].signal instanceof AbortSignal);
sockets[1].events.open();
sockets[1].close();
status = 403;
const delays = [];
for (let i = 0; i < 12; i++) delays.push(await retry());
assert.equal(sockets.length, 2, "failed metadata must not reconnect to stale settings");
assert.equal(delays[0], 500);
assert.equal(delays.at(-1), 8000);
assert.ok(delays.every(delay => delay >= 500 && delay <= 8000));
status = 200;
response = { wsPort: "2234" };
await retry();
assert.equal(sockets.length, 2, "invalid connection metadata is rejected");
response = { wsPort: 2234 };
await retry();
assert.equal(sockets[2].url.port, "2234");
assert.equal(timers.size, 0, "successful refresh clears its fetch timeout");

// A stalled metadata read is aborted and retried, rather than blocking forever.
sockets[2].events.open();
sockets[2].close();
stalled = true;
const [retryId, retryTimer] = timers.entries().next().value;
timers.delete(retryId);
const pending = retryTimer.fn();
const [timeoutId, timeout] = timers.entries().next().value;
assert.equal(timeout.delay, 5000);
timers.delete(timeoutId);
timeout.fn();
await pending;
assert.equal(sockets.length, 3);
assert.equal(timers.size, 1, "aborted metadata read schedules exactly one retry");
stalled = false;
await retry();
assert.equal(sockets.length, 4);
console.log("OBS reconnect: changed/missed ports, auth, bounded backoff, invalid metadata and read timeout passed");
